import argparse
import csv
import json
from datetime import datetime, timezone, timedelta

def parse_timestamp(timestamp_str):
    # Handle 'Z' for UTC
    if timestamp_str.endswith('Z'):
        timestamp_str = timestamp_str[:-1] + '+00:00'
    return datetime.fromisoformat(timestamp_str)

def main():
    parser = argparse.ArgumentParser(description='Reconcile payment transactions from a CSV file.')
    parser.add_argument('csv_file', help='Path to the input CSV file')
    args = parser.parse_args()

    transactions = {}

    try:
        with open(args.csv_file, mode='r', newline='', encoding='utf-8') as f:
            reader = csv.DictReader(f)
            for i, row in enumerate(reader):
                tx_id = row['tx_id']
                timestamp = parse_timestamp(row['timestamp'])
                amount = int(row['amount'])
                status = row['status']

                current_transaction = {
                    'tx_id': tx_id,
                    'timestamp': timestamp,
                    'amount': amount,
                    'status': status,
                    'line_num': i  # To handle same-instant tie-breaking
                }

                if tx_id not in transactions or \
                   timestamp > transactions[tx_id]['timestamp'] or \
                   (timestamp == transactions[tx_id]['timestamp'] and i > transactions[tx_id]['line_num']):
                    transactions[tx_id] = current_transaction

    except FileNotFoundError:
        parser.error(f"Input CSV file not found: {args.csv_file}")
    except KeyError as e:
        parser.error(f"Missing expected column in CSV: {e}")
    except ValueError as e:
        parser.error(f"Error parsing transaction data: {e}")

    total_valid_amount = 0
    valid_count = 0
    failed_count = 0

    for tx in transactions.values():
        if tx['status'] == 'VALID':
            total_valid_amount += tx['amount']
            valid_count += 1
        elif tx['status'] == 'FAILED':
            failed_count += 1

    output = {
        'total_valid_amount': total_valid_amount,
        'valid_count': valid_count,
        'failed_count': failed_count
    }

    print(json.dumps(output, indent=None))

if __name__ == '__main__':
    main()

